 const timeline=current.current.t;if(!timeline||busy)return;e.preventDefault();e.stopPropagation();setSelection({kind,id:identity});setPlaying(false);const field=kind==='clip'?'clips':kind==='audio'?'audio':'titles',item=(timeline[field] as any[]).find(c=>c.id===identity);if(!item)return;const info=item.source?inspected[key(item.source)]:undefined;if(kind!=='title'&&!info){setError('Reading this source. Try its handle again in a moment.');return;}
