 {t.clips.map(c=>{const problem=audioOffsetProblem(c,c.source.kind==='gap'?{audio:false,duration:60}:inspected[key(c.source)],t.output.fps);return problem&&<div className="ed-error" role="alert" key={c.id}><span>{problem}</span><button aria-label={'Reset audio offset for '+c.label} onClick={()=>change({clips:t.clips.map(x=>x.id===c.id?{...x,audio_offset:0}:x)})}>Reset audio offset</button></div>;})}
